-- ============================================
-- LUMA — Thème 4 (Voyage) : 3 scénarios COURTS x4
-- ============================================


update scenarios set content = '{"characters": {"agent": "l''agent au comptoir"}, "start_node": "n1", "nodes": {"n1": {"speaker": "agent", "text": "Good morning! Passport and ticket, please.", "text_fr": "Bonjour ! Passeport et billet, s''il vous plaît.", "choices": [{"text": "Here you go.", "text_fr": "Voici.", "next": "n2"}, {"text": "Here you are — I also have a question about my seat.", "text_fr": "Voici — j''ai aussi une question sur mon siège.", "next": "n2b"}]}, "n2": {"speaker": "agent", "text": "Thank you. Do you have any bags to check in?", "text_fr": "Merci. Vous avez des bagages à enregistrer ?", "choices": [{"text": "Yes, just this one suitcase.", "text_fr": "Oui, juste cette valise.", "next": "n3"}, {"text": "No, just my carry-on today.", "text_fr": "Non, juste mon bagage à main aujourd''hui.", "next": "n3b"}]}, "n2b": {"speaker": "agent", "text": "Sure, what''s your question about the seat?", "text_fr": "Bien sûr, quelle est votre question sur le siège ?", "choices": [{"text": "Could I get a window seat if possible?", "text_fr": "Je pourrais avoir un siège côté hublot si possible ?", "next": "n3c"}]}, "n3": {"speaker": "agent", "text": "Let me weigh that for you. (checks) It''s within the limit, perfect.", "text_fr": "Laissez-moi peser ça pour vous. (vérifie) C''est dans la limite, parfait.", "choices": [{"text": "Great, thank you.", "text_fr": "Super, merci.", "next": "n4"}]}, "n3b": {"speaker": "agent", "text": "No problem, just make sure it fits the size requirements.", "text_fr": "Aucun problème, assurez-vous juste que ça respecte les dimensions autorisées.", "choices": [{"text": "It should, I checked before leaving.", "text_fr": "Ça devrait, j''ai vérifié avant de partir.", "next": "n4"}]}, "n3c": {"speaker": "agent", "text": "Let me check availability... yes, I can give you 14A, a window seat.", "text_fr": "Laissez-moi vérifier la disponibilité... oui, je peux vous donner le 14A, un siège hublot.", "choices": [{"text": "Perfect, thank you so much.", "text_fr": "Parfait, merci beaucoup.", "next": "n4"}]}, "n4": {"speaker": "agent", "text": "Here''s your boarding pass. Gate B12, boarding starts at 2:30pm.", "text_fr": "Voici votre carte d''embarquement. Porte B12, embarquement à 14h30.", "choices": [{"text": "Thank you, is there anywhere good to eat near that gate?", "text_fr": "Merci, il y a un bon endroit pour manger près de cette porte ?", "next": "n5"}, {"text": "Perfect, thank you for your help.", "text_fr": "Parfait, merci pour votre aide.", "next": "n5b"}]}, "n5": {"speaker": "agent", "text": "Yes, there''s a nice café right past security in that terminal.", "text_fr": "Oui, il y a un chouette café juste après la sécurité dans ce terminal.", "choices": [{"text": "Perfect, I''ll check that out. Thanks again!", "text_fr": "Parfait, je vais aller voir. Merci encore !", "next": "end_smooth"}]}, "n5b": {"speaker": "agent", "text": "You''re welcome, have a great flight!", "text_fr": "Je vous en prie, bon vol !", "choices": [{"text": "Thank you, have a good day!", "text_fr": "Merci, bonne journée !", "next": "end_smooth"}]}, "end_smooth": {"speaker": "agent", "text": "Safe travels!", "text_fr": "Bon voyage !", "end": true, "ending_label": "Enregistrement fluide et sans accroc ✈️"}}}'::jsonb, is_playable = true
where title = 'Enregistrement et bagages'
  and theme_id = (select id from scenario_themes where position = 4 and language_id = (select id from languages where code = 'en'));


update scenarios set content = '{"characters": {"officer": "l''agent des douanes"}, "start_node": "n1", "nodes": {"n1": {"speaker": "officer", "text": "Passport, please. What''s the purpose of your visit?", "text_fr": "Passeport, s''il vous plaît. Quel est le but de votre visite ?", "choices": [{"text": "Tourism — I''m here for a two-week vacation.", "text_fr": "Tourisme — je suis là pour deux semaines de vacances.", "next": "n2"}, {"text": "Business — I have meetings with a client here.", "text_fr": "Affaires — j''ai des réunions avec un client ici.", "next": "n2b"}]}, "n2": {"speaker": "officer", "text": "Nice, where are you planning to stay?", "text_fr": "Bien, où comptez-vous séjourner ?", "choices": [{"text": "At a hotel downtown, I have the reservation here.", "text_fr": "Dans un hôtel en centre-ville, j''ai la réservation ici.", "next": "n3"}, {"text": "With a friend who lives in the city.", "text_fr": "Chez un ami qui habite en ville.", "next": "n3"}]}, "n2b": {"speaker": "officer", "text": "I see. How long will you be staying?", "text_fr": "Je vois. Combien de temps allez-vous rester ?", "choices": [{"text": "Just three days, then I fly back.", "text_fr": "Juste trois jours, puis je repars.", "next": "n3"}]}, "n3": {"speaker": "officer", "text": "And do you have a return ticket booked?", "text_fr": "Et vous avez un billet retour réservé ?", "choices": [{"text": "Yes, right here on my phone.", "text_fr": "Oui, juste ici sur mon téléphone.", "next": "n4"}, {"text": "Yes, I can show you the confirmation email.", "text_fr": "Oui, je peux vous montrer l''email de confirmation.", "next": "n4"}]}, "n4": {"speaker": "officer", "text": "Perfect, that''s all I need. Anything to declare?", "text_fr": "Parfait, c''est tout ce dont j''ai besoin. Quelque chose à déclarer ?", "choices": [{"text": "No, nothing to declare.", "text_fr": "Non, rien à déclarer.", "next": "n5"}, {"text": "Just some gifts for family, nothing valuable.", "text_fr": "Juste des cadeaux pour la famille, rien de valeur.", "next": "n5"}]}, "n5": {"speaker": "officer", "text": "Great, welcome! Enjoy your stay.", "text_fr": "Super, bienvenue ! Profitez de votre séjour.", "choices": [{"text": "Thank you very much.", "text_fr": "Merci beaucoup.", "next": "end_cleared"}]}, "end_cleared": {"speaker": "officer", "text": "Next, please!", "text_fr": "Suivant, s''il vous plaît !", "end": true, "ending_label": "Passage en douane sans encombre 🛂"}}}'::jsonb, is_playable = true
where title = 'Une question à la douane'
  and theme_id = (select id from scenario_themes where position = 4 and language_id = (select id from languages where code = 'en'));
